def find_minimal_edit(s_in, s_out):
    """Find the minimal edit between two strings."""
    # Simple approach: find first differing position and determine what needs to change
    min_len = min(len(s_in), len(s_out))

    # Find first difference
    pos = -1
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            pos = i
            break

    if pos == -1:
        # One string is prefix of other
        if len(s_in) < len(s_out):
            return (s_in[len(s_in):], s_out[len(s_in):], len(s_in))
        else:
            return (s_in[len(s_out):], s_out[len(s_out):], len(s_out))

    # Find the substring that needs to be replaced
    # We'll look for the longest matching prefix/suffix to determine what to replace
    old_sub = ""
    new_sub = ""

    # Try to find what's being replaced by looking at character differences
    for i in range(pos, len(s_in)):
        if i >= len(s_out):
            break
        if s_in[i] != s_out[i]:
            old_sub += s_in[i]
            new_sub += s_out[i]
        else:
            break

    if not old_sub:
        # Check if we're appending or prepending
        if len(s_in) < len(s_out):
            old_sub = ""
            new_sub = s_out[len(s_in):]
        else:
            old_sub = s_in[len(s_out):]
            new_sub = ""

    return (old_sub, new_sub, pos)

# Analyze each changed pair
changed = [(0, 'fchwby', 'fchkvubfz'), (3, 'ivydfd', 'aacedfd'), (4, 'guwa', 'gukvua')]

for idx, inp, outp in changed:
    old, new, pos = find_minimal_edit(inp, outp)
    print(f"Pair {idx}: '{inp}' -> '{outp}' at pos {pos}")
    print(f"  Old sub: '{old}', New sub: '{new}'")

